import{_ as i,o as a,c as n,a6 as s}from"./chunks/framework.DL_pga9_.js";const h=JSON.parse('{"title":"Ranges, Slicing, Fold, And Pipeline Syntax","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/ranges_slicing_pipeline_baseline.md","filePath":"design/archive/ranges_slicing_pipeline_baseline.md","lastUpdated":1780030916000}'),l={name:"design/archive/ranges_slicing_pipeline_baseline.md"};function o(t,e,d,c,r,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="ranges-slicing-fold-and-pipeline-syntax" tabindex="-1">Ranges, Slicing, Fold, And Pipeline Syntax <a class="header-anchor" href="#ranges-slicing-fold-and-pipeline-syntax" aria-label="Permalink to “Ranges, Slicing, Fold, And Pipeline Syntax”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 10.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Define collection-oriented syntax that was originally discussed alongside tuples but is not a prerequisite for enhanced generics or tuple type introspection.</p><p>This design is intentionally last in the current dependency order because it adds surface syntax and collection semantics rather than foundational type/module infrastructure.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li>Current tuple and array value semantics.</li><li><a href="./../enhanced_tuples">Enhanced Tuple Types</a>, if tuple slicing must preserve exact tuple element types.</li><li><a href="./constant_generic_parameters">Constant Generic Parameters</a>, for compile-time tuple slice bounds.</li></ul><p>Optional:</p><ul><li><a href="./stdlib_modularization">Standard Library Modularization</a>, for exposing sequence container APIs. Range, slice, and fold syntax is not implemented as stdlib helper calls.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li>Range operator syntax: <code>a..b</code>, <code>a..=b</code>, <code>..b</code>, <code>a..</code>.</li><li>From-end index syntax: <code>^n</code>.</li><li>Array and tuple indexing with ranges.</li><li>Tuple slicing type preservation for compile-time bounds.</li><li>Postfix fold expressions for map/filter/fold over one sequence.</li><li>Pipeline syntax as ordinary call composition, independent from fold syntax.</li></ul><p>Out of scope:</p><ul><li>Tuple value basics.</li><li>Generic pack mechanics.</li><li>Module system changes.</li><li>Multi-sequence zip/map2 and zip-with forms.</li><li>N-ary fold over functions with more than one sequence input.</li><li>General meaning for <code>?</code> outside the fixed <code>?...</code> filter marker.</li></ul><h2 id="current-baseline" tabindex="-1">Current Baseline <a class="header-anchor" href="#current-baseline" aria-label="Permalink to “Current Baseline”">​</a></h2><p>Already exists:</p><ul><li>Lexer tokens for <code>..</code>, <code>..=</code>, <code>...</code>, and <code>^</code>.</li></ul><p>Implemented in this phase:</p><ul><li>Range expressions as AST/typechecked/runtime values for integral bounds, producing <code>Range&lt;T&gt;</code> values. Unsuffixed integer bounds default to <code>Range&lt;i32&gt;</code>, while typed bounds such as <code>1u32..10u32</code> produce <code>Range&lt;u32&gt;</code>.</li><li>End-exclusive <code>a..b</code> and end-inclusive <code>a..=b</code>.</li><li>Open ranges inside index access: <code>xs[..b]</code> and <code>xs[a..]</code>.</li><li>From-end index syntax <code>xs[^n]</code>.</li><li>Vector/fixed-array slicing with <code>xs[a..b]</code>, producing a <code>span&lt;T&gt;</code> view.</li><li>Tuple slicing with compile-time bounds and preserved tuple type shape.</li><li>General pipeline syntax <code>value |&gt; f</code> and <code>value |&gt; f(args...)</code>, lowered to <code>f(value)</code> and <code>f(value, args...)</code>.</li><li>Postfix fold expressions for single-sequence map/filter/fold using direct local non-generic functions: <code>[mapper(xs)...]</code>, <code>[predicate(xs)?...]</code>, <code>op(xs..., init)</code>, and <code>op(init, xs...)</code>.</li><li>Mixed array literals containing map/filter fold segments: <code>[0, mapper(xs)..., 9]</code>.</li><li>Range/span materialization through spread in array literals: <code>[...(0..4)]</code> and <code>[...xs[1..3]]</code>.</li><li><code>std.seq.Sequence&lt;T&gt;</code> exposes <code>size</code> and <code>get</code>; vector, fixed array, span, Range, and the NG-authored <code>std.list.List&lt;T&gt;</code> satisfy the protocol.</li><li><code>List&lt;T&gt;</code> can be materialized through spread in both STUPID and ORGASM via the same <code>Sequence&lt;T&gt;</code> <code>size</code>/<code>get</code> protocol.</li><li><code>listof&lt;T&gt;(args: T...) -&gt; List&lt;T&gt;</code> uses homogeneous varargs: <code>T</code> is a single element type, while <code>T...</code> in the parameter annotation collects runtime arguments into a sequence value.</li><li><code>List&lt;T&gt;</code> has inherent <code>pushBack</code>, <code>append</code>, <code>size</code>, and <code>get</code> methods. The exported free <code>pushBack</code>/<code>append</code>/<code>get</code> wrappers remain available as ordinary stdlib functions for code that wants explicit ref-passing.</li></ul><p>Still not implemented:</p><ul><li>Range step syntax.</li><li>Multi-sequence zip/map2 and n-ary fold.</li><li>Postfix fold expressions targeting imported, native, generic, or indirect function values.</li><li>Richer <code>Sequence&lt;T&gt;</code> algorithms beyond the current <code>size</code>/<code>get</code> protocol.</li><li><code>std.list</code> is implemented in NG rather than as a native runtime container.</li></ul><h2 id="fold-expressions" tabindex="-1">Fold Expressions <a class="header-anchor" href="#fold-expressions" aria-label="Permalink to “Fold Expressions”">​</a></h2><p>Fold expressions use postfix <code>...</code> in value-expression contexts. This is separate from existing prefix spread/unpack <code>...expr</code>, and separate from type pack syntax such as <code>T...</code>.</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val xs = [1, 2, 3];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val ys = [inc(xs)...];       // map: equivalent to map(inc, xs)</span></span>
<span class="line"><span>val evens = [even(xs)?...];  // filter: equivalent to filter(even, xs)</span></span>
<span class="line"><span>val total_r = plus(xs..., 0); // foldr: plus(x0, plus(x1, plus(x2, 0)))</span></span>
<span class="line"><span>val total_l = plus(0, xs...); // foldl: plus(plus(plus(0, x0), x1), x2)</span></span></code></pre></div><p>Parser/typechecker rules:</p><ul><li><code>...expr</code> keeps its existing unpack/spread meaning.</li><li><code>expr...</code> is a postfix fold expression only in value-expression contexts.</li><li><code>predicate(expr)?...</code> is the only filter marker form in this phase; <code>?</code> has no general expression meaning outside the fixed <code>?...</code> token sequence.</li><li>Map and filter expressions must contain exactly one driver sequence expression in this phase. Multiple driver sequences are rejected instead of implicitly zipping.</li><li><code>seq...</code> in the first call-argument position with an initializer after it is a right fold.</li><li><code>seq...</code> in the last call-argument position with an initializer before it is a left fold.</li><li><code>seq...</code> in a middle argument position is rejected in this phase.</li><li>A call expression may contain at most one postfix fold pack.</li><li>Fold operators are checked as binary functions. For foldr, the function must accept <code>(element, accumulator)</code>; for foldl, it must accept <code>(accumulator, element)</code>.</li></ul><p>Future plan:</p><ul><li>Add zip/map2 syntax for multiple driver sequences after the single-sequence rules are stable.</li><li>Add n-ary fold only after the type checker can model multi-argument accumulator transitions explicitly.</li><li>Decide whether <code>?</code> should gain any standalone expression meaning. Until then, only <code>?...</code> is reserved for filter-fold syntax.</li></ul><h2 id="design-questions" tabindex="-1">Design Questions <a class="header-anchor" href="#design-questions" aria-label="Permalink to “Design Questions”">​</a></h2><ul><li>Ranges with both bounds are first-class <code>Range&lt;T&gt;</code> values.</li><li>Open ranges are index-only.</li><li><code>a..b</code> is end-exclusive and <code>a..=b</code> is end-inclusive.</li><li>Descending ranges use the same <code>Range&lt;T&gt;</code> runtime representation; explicit step remains future work.</li><li>Pipeline syntax is general call sugar, not collection-only sugar.</li><li>Fold expressions use postfix <code>...</code>; <code>|&gt;</code> never triggers map/filter/fold semantics by itself.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li><code>range(0, 3)</code>, <code>slice(xs, 0, 2)</code>, and stdlib <code>fold(...)</code> helper calls are no longer exported compatibility APIs.</li><li><code>xs[1..3]</code> works for vectors/fixed arrays and returns <code>span&lt;T&gt;</code>.</li><li><code>[...(0..3)]</code> and <code>[...xs[1..3]]</code> materialize ranges/spans into vectors.</li><li><code>tuple[1..3]</code> works when bounds are compile-time constants and returns a tuple with preserved element types.</li><li><code>xs[^1]</code> indexes from the end when the collection has runtime length.</li><li>Invalid tuple slice bounds fail during type checking.</li><li>Fold/pipeline syntax has a separate parser/typechecker test suite before runtime lowering.</li></ul>`,34)])])}const g=i(l,[["render",o]]);export{h as __pageData,g as default};
